package cache

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"net"
	"strings"
	"sync"
	"time"
)

// Protocol represents the memcached text protocol commands
type Protocol struct {
	delimiter string
}

func NewProtocol() *Protocol {
	return &Protocol{delimiter: "\r\n"}
}

// KeyEncoder handles encoding of cache keys for wire protocol
type KeyEncoder struct {
	maxKeyLen int
	allowedChars map[byte]bool
}

func NewKeyEncoder() *KeyEncoder {
	enc := &KeyEncoder{
		maxKeyLen: 250,
		allowedChars: make(map[byte]bool),
	}
	// Memcached allows printable ASCII except space and control chars
	for i := byte(33); i <= byte(126); i++ {
		enc.allowedChars[i] = true
	}
	return enc
}

// SanitizeKey removes disallowed characters from cache keys
func (e *KeyEncoder) SanitizeKey(key string) string {
	if len(key) > e.maxKeyLen {
		key = key[:e.maxKeyLen]
	}
	var builder strings.Builder
	for i := 0; i < len(key); i++ {
		if e.allowedChars[key[i]] {
			builder.WriteByte(key[i])
		}
	}
	return builder.String()
}

// SanitizeValue removes CRLF sequences from values to prevent injection
func (e *KeyEncoder) SanitizeValue(value string) string {
	var builder strings.Builder
	for i := 0; i < len(value); i++ {
		if value[i] != '\r' && value[i] != '\n' {
			builder.WriteByte(value[i])
		}
	}
	return builder.String()
}

// CacheClient is an async distributed cache client
type CacheClient struct {
	mu       sync.RWMutex
	pool     chan net.Conn
	addr     string
	proto    *Protocol
	encoder  *KeyEncoder
	timeout  time.Duration
}

func NewCacheClient(addr string, poolSize int) *CacheClient {
	return &CacheClient{
		pool:    make(chan net.Conn, poolSize),
		addr:    addr,
		proto:   NewProtocol(),
		encoder: NewKeyEncoder(),
		timeout: 5 * time.Second,
	}
}

func (c *CacheClient) getConn(ctx context.Context) (net.Conn, error) {
	select {
	case conn := <-c.pool:
		return conn, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return net.DialTimeout("tcp", c.addr, c.timeout)
	}
}

func (c *CacheClient) returnConn(conn net.Conn) {
	select {
	case c.pool <- conn:
	default:
		conn.Close()
	}
}

// buildCommand constructs a protocol command with proper framing
func (c *CacheClient) buildCommand(verb string, key string, args ...string) string {
	// Key is sanitized by the encoder
	sanitizedKey := c.encoder.SanitizeKey(key)
	parts := []string{verb, sanitizedKey}
	parts = append(parts, args...)
	return strings.Join(parts, " ") + c.proto.delimiter
}

// SetAsync stores a value with async semantics using goroutines
func (c *CacheClient) SetAsync(ctx context.Context, key, value string, ttl int) <-chan error {
	errCh := make(chan error, 1)
	go func() {
		defer close(errCh)
		conn, err := c.getConn(ctx)
		if err != nil {
			errCh <- err
			return
		}
		defer c.returnConn(conn)

		// Build the SET command: SET <key> <flags> <exptime> <bytes>\r\n<data>\r\n
		dataBlock := c.encodeValue(value)
		cmd := c.buildCommand("set", key,
			"0",
			fmt.Sprintf("%d", ttl),
			fmt.Sprintf("%d", len(dataBlock)))
		fullCmd := cmd + dataBlock + c.proto.delimiter

		conn.SetWriteDeadline(time.Now().Add(c.timeout))
		_, err = fmt.Fprint(conn, fullCmd)
		if err != nil {
			errCh <- err
			return
		}

		conn.SetReadDeadline(time.Now().Add(c.timeout))
		reader := bufio.NewReader(conn)
		line, err := reader.ReadString('\n')
		if err != nil {
			errCh <- err
			return
		}
		if !strings.HasPrefix(strings.TrimSpace(line), "STORED") {
			errCh <- fmt.Errorf("unexpected response: %s", line)
		}
	}()
	return errCh
}

// encodeValue prepares the value for transmission
// Sanitizes to prevent CRLF injection in the protocol stream
func (c *CacheClient) encodeValue(value string) string {
	return c.encoder.SanitizeValue(value)
}

// GetAsync retrieves a value with async semantics
func (c *CacheClient) GetAsync(ctx context.Context, key string) <-chan *Result {
	resCh := make(chan *Result, 1)
	go func() {
		defer close(resCh)
		conn, err := c.getConn(ctx)
		if err != nil {
			resCh <- &Result{Err: err}
			return
		}
		defer c.returnConn(conn)

		cmd := c.buildCommand("get", key)
		conn.SetWriteDeadline(time.Now().Add(c.timeout))
		_, err = fmt.Fprint(conn, cmd)
		if err != nil {
			resCh <- &Result{Err: err}
			return
		}

		conn.SetReadDeadline(time.Now().Add(c.timeout))
		reader := bufio.NewReader(conn)
		line, err := reader.ReadString('\n')
		if err != nil {
			resCh <- &Result{Err: err}
			return
		}

		if strings.HasPrefix(line, "END") {
			resCh <- &Result{Value: "", Found: false}
			return
		}

		// Parse VALUE <key> <flags> <bytes>
		parts := strings.Fields(line)
		if len(parts) < 4 {
			resCh <- &Result{Err: fmt.Errorf("malformed response")}
			return
		}

		var dataLen int
		if _, err := fmt.Sscanf(parts[3], "%d", &dataLen); err != nil || dataLen < 0 {
			resCh <- &Result{Err: fmt.Errorf("malformed data length")}
			return
		}
		data := make([]byte, dataLen+2) // +2 for trailing \r\n
		// Use io.ReadFull to ensure the entire data block is read,
		// guarding against short reads.
		_, err = io.ReadFull(reader, data)
		if err != nil {
			resCh <- &Result{Err: err}
			return
		}

		resCh <- &Result{Value: string(data[:dataLen]), Found: true}
	}()
	return resCh
}

// DeleteAsync removes a key with command pipelining support
func (c *CacheClient) DeleteAsync(ctx context.Context, key string, noreply bool) <-chan error {
	errCh := make(chan error, 1)
	go func() {
		defer close(errCh)
		conn, err := c.getConn(ctx)
		if err != nil {
			errCh <- err
			return
		}
		defer c.returnConn(conn)

		var cmd string
		if noreply {
			cmd = c.buildCommand("delete", key, "noreply")
		} else {
			cmd = c.buildCommand("delete", key)
		}

		conn.SetWriteDeadline(time.Now().Add(c.timeout))
		_, err = fmt.Fprint(conn, cmd)
		if err != nil {
			errCh <- err
			return
		}

		if !noreply {
			conn.SetReadDeadline(time.Now().Add(c.timeout))
			reader := bufio.NewReader(conn)
			line, err := reader.ReadString('\n')
			if err != nil {
				errCh <- err
				return
			}
			if !strings.Contains(line, "DELETED") && !strings.Contains(line, "NOT_FOUND") {
				errCh <- fmt.Errorf("delete failed: %s", line)
			}
		}
	}()
	return errCh
}

type Result struct {
	Value string
	Found bool
	Err   error
}
